<rect width="216" height="200" fill="url(#pattern0_201_2161)"/>
<defs>
<pattern id="pattern0_201_2161" patternContentUnits="objectBoundingBox" width="1" height="1">
<use xlink:href="#image0_201_2161" transform="matrix(0.00423554 0 0 0.00457589 -0.181818 -0.214286)"/>
</pattern>
<image id="image0_201_2161" width="320" height="320" preserveAspectRatio="none" xlink:href="data:image/png;base64,"/>
</defs>
</svg>''';

